INSERT INTO dw_function_units (code, name, display_name, icon_id, status, current_version, version, is_active, enabled, deployed_at, previous_version_id, lock_version, created_by, created_at, updated_by, updated_at, tags, startup_mode) VALUES ('fu-call-demo-vendor', 'Vendor Qualification Check', 'Called sub-process: reviews one vendor''s qualification and returns a verdict. Startup Mode is Callable, so it runs only when another Function Unit calls it.', NULL, 'PUBLISHED', '1.0.1', '1.0.0', true, true, '2026-10-07 03:19:38.961949', NULL, 2, 'system', '2026-10-07 03:19:38.961949', 'developer', '2026-10-07 04:15:25.390816', $json$[]$json$::jsonb, 'CALLABLE')
INSERT INTO dw_function_units (code, name, display_name, icon_id, status, current_version, version, is_active, enabled, deployed_at, previous_version_id, lock_version, created_by, created_at, updated_by, updated_at, tags, startup_mode) VALUES ('fu-call-demo-purchase', 'Purchase Request (Function Unit Calls)', 'Demonstrates one Function Unit calling another: a single call for the primary vendor, one call per row for additional vendors, and a multi-instance sub-task block alongside them to show the two mechanisms coexist. Rejecting a called check fails this request.', NULL, 'PUBLISHED', '1.0.19', '1.0.0', true, true, '2026-10-07 03:20:03.55097', NULL, 21, 'system', '2026-10-07 03:20:03.55097', 'developer', '2026-10-08 10:07:26.198168', $json$[]$json$::jsonb, 'STANDALONE')
INSERT INTO dw_table_definitions (id, function_unit_id, table_name, table_display_name, table_type, display_name, request_id_config, created_at, updated_at) VALUES (50335, (SELECT id FROM dw_function_units WHERE code = 'fu-call-demo-vendor'), 'vendor_check', 'Vendor Check', 'MAIN', 'One qualification check: the vendor reviewed and the verdict reached.', NULL, '2026-10-07 03:19:39.378603', '2026-10-07 04:14:43.18496');
INSERT INTO dw_table_definitions (id, function_unit_id, table_name, table_display_name, table_type, display_name, request_id_config, created_at, updated_at) VALUES (50336, (SELECT id FROM dw_function_units WHERE code = 'fu-call-demo-purchase'), 'purchase_request', 'Purchase Request', 'MAIN', 'The purchase request being raised.', $json${"separator": "-", "fieldNames": ["title", "department"]}$json$::jsonb, '2026-10-07 03:20:03.982011', '2026-10-07 11:00:50.910334');
