-- =============================================================================
-- 24-fu-call-demo / 00-init: both Function Units of the call demo
--
--   fu-call-demo-vendor    Vendor Qualification Check               CALLABLE    (the one being called)
--   fu-call-demo-purchase  Purchase Request (Function Unit Calls)   STANDALONE  (the caller)
--
-- Exported from the dev DB on 2026-10-09 (vendor current_version 1.0.1, purchase
-- current_version 1.0.19). The callee is written first: the caller's call
-- activities reference it by code.
--
-- Scope: developer-workstation catalog only (dw_*). The function unit rows are
-- upserted by code and keep their own id; every child row references its unit
-- by code. Not seeded: dw_versions history, dw_deployment_jobs, sys_* (deploy
-- from Developer Workstation as described in README.md), runtime up_* data.
-- The RELATED binding on the Purchase Request Form points at the built-in
-- read-only users table (-1000000001), which needs no rt_* rows.
--
-- Idempotent: the cleanup block removes the units' design rows before the
-- inserts, so re-running it on any database converges to the same state.
-- Snapshot file: regenerate it from the DB rather than hand-editing rows.
-- =============================================================================
BEGIN;

DO $cleanup$
DECLARE v_fu_id bigint;
BEGIN
  FOR v_fu_id IN
    SELECT id FROM dw_function_units
    WHERE code IN ('fu-call-demo-vendor', 'fu-call-demo-purchase')
  LOOP
    DELETE FROM dw_main_table_view_access
      WHERE view_config_id IN (SELECT id FROM dw_main_table_view_configs WHERE function_unit_id = v_fu_id);
    DELETE FROM dw_main_table_view_fields
      WHERE view_config_id IN (SELECT id FROM dw_main_table_view_configs WHERE function_unit_id = v_fu_id);
    DELETE FROM dw_main_table_view_configs WHERE function_unit_id = v_fu_id;

    DELETE FROM dw_sub_table_view_fields
      WHERE view_config_id IN (
        SELECT c.id FROM dw_sub_table_view_configs c
        WHERE c.binding_id IN (
          SELECT id FROM dw_form_table_bindings
          WHERE form_id IN (SELECT id FROM dw_form_definitions WHERE function_unit_id = v_fu_id)
        )
      );
    DELETE FROM dw_sub_table_view_configs
      WHERE binding_id IN (
        SELECT id FROM dw_form_table_bindings
        WHERE form_id IN (SELECT id FROM dw_form_definitions WHERE function_unit_id = v_fu_id)
      );

    DELETE FROM dw_form_stage_bindings WHERE form_id IN (SELECT id FROM dw_form_definitions WHERE function_unit_id = v_fu_id);
    -- dw_form_table_bindings.table_id has no ON DELETE CASCADE: bindings go before tables.
    DELETE FROM dw_form_table_bindings WHERE form_id IN (SELECT id FROM dw_form_definitions WHERE function_unit_id = v_fu_id);
    DELETE FROM dw_link_form_components WHERE function_unit_id = v_fu_id;
    DELETE FROM dw_form_definitions WHERE function_unit_id = v_fu_id;
    DELETE FROM dw_process_definitions WHERE function_unit_id = v_fu_id;
    DELETE FROM dw_action_definitions WHERE function_unit_id = v_fu_id;
    DELETE FROM dw_decision_definitions WHERE function_unit_id = v_fu_id;
    DELETE FROM dw_email_monitor_rules WHERE function_unit_id = v_fu_id;
    DELETE FROM dw_email_templates WHERE function_unit_id = v_fu_id;
    DELETE FROM dw_email_connections WHERE function_unit_id = v_fu_id;
    DELETE FROM dw_table_relations WHERE function_unit_id = v_fu_id;
    DELETE FROM dw_foreign_keys
      WHERE table_id IN (SELECT id FROM dw_table_definitions WHERE function_unit_id = v_fu_id)
         OR ref_table_id IN (SELECT id FROM dw_table_definitions WHERE function_unit_id = v_fu_id);
    DELETE FROM dw_field_definitions WHERE table_id IN (SELECT id FROM dw_table_definitions WHERE function_unit_id = v_fu_id);
    DELETE FROM dw_table_definitions WHERE function_unit_id = v_fu_id;
  END LOOP;
END $cleanup$;

  ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, display_name = EXCLUDED.display_name, icon_id = EXCLUDED.icon_id, status = EXCLUDED.status, current_version = EXCLUDED.current_version, version = EXCLUDED.version, is_active = EXCLUDED.is_active, enabled = EXCLUDED.enabled, deployed_at = EXCLUDED.deployed_at, previous_version_id = EXCLUDED.previous_version_id, lock_version = EXCLUDED.lock_version, created_by = EXCLUDED.created_by, created_at = EXCLUDED.created_at, updated_by = EXCLUDED.updated_by, updated_at = EXCLUDED.updated_at, tags = EXCLUDED.tags, startup_mode = EXCLUDED.startup_mode;
  ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, display_name = EXCLUDED.display_name, icon_id = EXCLUDED.icon_id, status = EXCLUDED.status, current_version = EXCLUDED.current_version, version = EXCLUDED.version, is_active = EXCLUDED.is_active, enabled = EXCLUDED.enabled, deployed_at = EXCLUDED.deployed_at, previous_version_id = EXCLUDED.previous_version_id, lock_version = EXCLUDED.lock_version, created_by = EXCLUDED.created_by, created_at = EXCLUDED.created_at, updated_by = EXCLUDED.updated_by, updated_at = EXCLUDED.updated_at, tags = EXCLUDED.tags, startup_mode = EXCLUDED.startup_mode;

-- Workspace visibility comes only from dev-group membership (see 00/04).
SELECT u.id, 'vg-dev-public', 'system', CURRENT_TIMESTAMP
FROM dw_function_units u
WHERE u.code IN ('fu-call-demo-vendor', 'fu-call-demo-purchase')
  AND NOT EXISTS (
    SELECT 1 FROM dw_function_unit_dev_groups g
    WHERE g.function_unit_id = u.id AND g.virtual_group_id = 'vg-dev-public');

COMMIT;
